  if ( t <= 66.0 ) g = clamp( 0.39008158 * log( t ) - 0.63184144, 0.0, 1.0 );
  else g = clamp( 1.12989086 * pow( t - 60.0, -0.07551485 ), 0.0, 1.0 );
  if ( t >= 66.0 ) b = 1.0;
  else if ( t <= 19.0 ) b = 0.0;
